/**
 * Superseded names, mapped to what replaced them.
 *
 * The key must never be published; the value says what to publish instead.
 * contracts/README.md rule 2 records these so a developer grepping the old module
 * prose lands on the canonical form rather than reintroducing the drift F-101
 * catalogued. The value is guidance rather than always a single type:
 * accounting_period.closed was split into two states with different consequences.
 */
export const FORBIDDEN_EVENT_NAMES: Readonly<Record<string, string>> = {
  'role.updated': "role.changed",
  'accounting_period.closed': "accounting_period.soft_closed | accounting_period.hard_closed",
  'bill.posted': "vendor_bill.posted",
  'bill.approved': "vendor_bill.approved",
  'bill.extracted': "ai.document_extracted (aggregate_type=vendor_bill)",
  'bill.match_exception': "vendor_bill.match_failed",
  'purchase_order.sent': "purchase_order.issued",
  'bank_feed.synced': "bank_feed.sync_completed",
  'reconciliation.finalized': "bank_reconciliation.completed",
  'transfer.posted': "bank_transfer.completed",
  'settlement.matched': "processor_settlement.reconciled",
  'depreciation.posted': "asset.depreciation_posted",
  'close_task.completed': "close.task_completed",
};
